<section class="section" id="studio"><div class="container"><div class="row mb-5"><div class="col-lg-9"><div class="label text-success mb-2">AI Design Studio</div><h2 class="display-5">Stop repeating yourself. The conversation is the brief.</h2><p class="lead-copy mt-3">If you say “6” after being asked for rooms, the system records 6. If you already said 20 × 30 m and five bedrooms, it keeps them. It will not send you back to the same question.</p></div></div><div class="studio"><div class="studio-head"><div><h3>Architecture workspace</h3><div class="muted" style="font-size:12px">Conversation · 2D planning · editable 3D</div></div><a class="tool" href="map.php">🗺 Open site map</a></div><div class="studio-grid"><section class="chat"><div class="chat-top"><div class="chat-status">● AI architect online</div><div class="muted" style="font-size:12px;margin-top:4px">Speak in English or Swahili. I remember what you have already told me.</div></div><div id="messages" class="messages"><div class="msg ai">Hello. Tell me the house you want to design. I will remember your answers instead of asking the same question again.</div><div class="msg system">Example: “Nataka nyumba ya kisasa ya vyumba vitano kwenye plot ya 20 × 30m. Living room iwe katikati na bedrooms ziizunguke.”</div></div><div class="chat-compose"><textarea id="chatInput" placeholder="Andika mahitaji ya nyumba…"></textarea><button id="sendBtn" class="send">➤</button></div></section><section class="workspace"><div class="workspace-bar"><button class="tool active" data-view="plan">2D Plan</button><button class="tool" data-view="three">3D Model</button><button class="tool" id="generateBtn">Generate</button><button class="tool" id="resetBtn">Reset</button><div class="workspace-tabs"><span id="planState" class="muted" style="font-size:11px">Waiting for your brief…</span></div></div><div id="planView" class="view active"><div class="plan-wrap"><div id="planBoard" class="plan-board"><div class="site-boundary"></div><div id="emptyPlan" class="empty-state">Tell the AI what you need.<br>When the critical requirements are known, press Generate.</div></div></div><div id="inspector" class="side-inspector" style="display:none"><div class="field name"><label>Room</label><input id="roomName"></div><div class="field"><label>Width m</label><input id="roomW" type="number" step="0.1"></div><div class="field"><label>Depth m</label><input id="roomD" type="number" step="0.1"></div><button class="tool" id="applyEdit">Apply</button><button class="tool" id="deleteRoom">Delete</button><div class="inspector-note">Drag rooms. Resize from the lower-right corner. Edits feed the 3D view.</div></div></div><div id="threeView" class="view"><div class="three"><div id="threeRoot"></div><div class="three-hint">Live 3D from the editable plan. Drag to orbit and use the wheel to zoom.</div><div class="three-tools"><button id="threeTop">Top</button><button id="threeIso">Isometric</button><button id="threeFront">Front</button></div></div></div></section></div><div id="summary" class="result-summary" style="display:none"><div class="container"><div id="summaryInner" class="summary-line"></div></div></div></div></div></section><section class="info-section" id="how"><div class="container"><div class="row g-5"><div class="col-md-4"><div class="label text-success mb-2">01 · Conversation</div><h3>Describe</h3><p>Give the house requirements naturally. The assistant extracts plot size, room count, bedrooms, courtyard, style and relationships.</p></div><div class="col-md-4"><div class="label text-success mb-2">02 · Planning</div><h3>Generate</h3><p>The plan is checked against hard constraints. A five-bedroom request cannot silently become ten bedrooms.</p></div><div class="col-md-4"><div class="label text-success mb-2">03 · Human control</div><h3>Edit</h3><p>Move rooms, change dimensions, delete or rename spaces, then inspect the same geometry in 3D.</p></div></div></div></section><footer><div class="container"><div class="eyebrow">Ramani Majengo</div><p class="mt-3 mb-0">AI-assisted architectural concept planning and GIS visualization. Preliminary concepts require qualified architectural and engineering review before construction.</p></div></footer><a class="floating-map" href="map.php">🗺 GIS Map</a><div id="loading" class="loading"><div class="loading-box"><h3>Building the architectural concept</h3><p class="muted">Checking requirements, planning spaces and preparing the editable model…</p><div class="bar"><i></i></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.min.js"></script><script src="https://cdn.jsdelivr.net/npm/three@0.180.0/examples/js/controls/OrbitControls.js"></script><script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.8/dist/js/bootstrap.bundle.min.js"></script><script>
const bgImages=['https://images.pexels.com/photos/7031607/pexels-photo-7031607.jpeg?auto=compress&cs=tinysrgb&w=1800','https://images.pexels.com/photos/323780/pexels-photo-323780.jpeg?auto=compress&cs=tinysrgb&w=1800','https://images.pexels.com/photos/1396122/pexels-photo-1396122.jpeg?auto=compress&cs=tinysrgb&w=1800','https://images.pexels.com/photos/1643383/pexels-photo-1643383.jpeg?auto=compress&cs=tinysrgb&w=1800','https://images.pexels.com/photos/1022936/pexels-photo-1022936.jpeg?auto=compress&cs=tinysrgb&w=1800','https://images.pexels.com/photos/259588/pexels-photo-259588.jpeg?auto=compress&cs=tinysrgb&w=1800'];let bi=0,ha=document.getElementById('heroA'),hb=document.getElementById('heroB');ha.style.backgroundImage=`url('${bgImages[0]}')`;setInterval(()=>{bi=(bi+1)%bgImages.length;hb.style.backgroundImage=`url('${bgImages[bi]}')`;hb.classList.add('show');ha.classList.remove('show');setTimeout(()=>{[ha,hb]=[hb,ha]},1300)},6500);
const state={plotW:null,plotD:null,bedrooms:null,totalSpaces:null,courtyard:false,brief:[],plan:null,selected:null};const $=id=>document.getElementById(id);function addMsg(t,k='ai'){const d=document.createElement('div');d.className='msg '+k;d.textContent=t;messages.appendChild(d);messages.scrollTop=messages.scrollHeight}function parse(t){const s=t.toLowerCase().replace(/×/g,'x');let m=s.match(/(\d+(?:\.\d+)?)\s*x\s*(\d+(?:\.\d+)?)/);if(m){state.plotW=+m[1];state.plotD=+m[2]}m=s.match(/(?:bedrooms?|bed\s*rooms?|vyumba\s+vya\s+kulala)\s*(?:=|:|ni|ya)?\s*(\d{1,2})\b/);if(m)state.bedrooms=+m[1];if(/\b(?:five|5)\s+(?:bedrooms?|vyumba)\b/.test(s))state.bedrooms=5;m=s.match(/(?:room(?:s)?|spaces?|vyumba)\s*(?:ziwe|viwe|=|:|ni)?\s*(\d{1,2})\b/);if(m)state.totalSpaces=+m[1];if(/^\s*\d{1,2}\s*$/.test(t)&&state.totalSpaces===null)state.totalSpaces=parseInt(t,10);if(/courtyard|uwanja\s+katikati|uwanja\s+(?:wa\s+)?ndani/i.test(s))state.courtyard=true;if(/vyumba hivyo vitano|vyumba vitano.*sebule|sebule.*katikati|five bedrooms?.*living|bedrooms?.*around.*living/i.test(s)){if(state.bedrooms===null)state.bedrooms=5;if(state.totalSpaces===null)state.totalSpaces=6}}function status(){const a=[];if(state.plotW&&state.plotD)a.push(`Plot ${state.plotW} × ${state.plotD}m`);if(state.bedrooms)a.push(`${state.bedrooms} bedrooms`);if(state.totalSpaces)a.push(`${state.totalSpaces} spaces`);if(state.courtyard)a.push('courtyard');$('planState').textContent=a.length?a.join(' · '):'Waiting for your brief…'}function missing(){if(!state.plotW||!state.plotD)return 'Nimehifadhi mahitaji yako. Kitu muhimu kinachokosekana ni ukubwa wa plot, mfano 20 × 30m.';if(!state.bedrooms&&!state.totalSpaces)return 'Nimehifadhi plot. Sasa niambie idadi kamili ya bedrooms au spaces kuu.';return null}$('sendBtn').onclick=()=>{const t=$('chatInput').value.trim();if(!t)return;addMsg(t,'user');$('chatInput').value='';parse(t);state.brief.push(t);status();const q=missing();if(q)addMsg(q);else if(/^\d+$/.test(t)&&state.totalSpaces)addMsg(`Sawa — nimehifadhi spaces kuu ${state.totalSpaces}. Sitakuuliza tena idadi hiyo.`);else addMsg(`Nimehifadhi ${state.plotW} × ${state.plotD}m${state.bedrooms?' · '+state.bedrooms+' bedrooms':''}${state.totalSpaces?' · '+state.totalSpaces+' spaces':''}${state.courtyard?' · central courtyard':''}. Ukiwa tayari bonyeza Generate.`)};$('chatInput').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('sendBtn').click()}});document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));$(b.dataset.view==='plan'?'planView':'threeView').classList.add('active');if(b.dataset.view==='three'&&state.plan)render3D()});
function esc(s){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}function renderPlan(p){state.plan=JSON.parse(JSON.stringify(p));const b=$('planBoard');b.querySelectorAll('.room').forEach(x=>x.remove());$('emptyPlan').style.display='none';const rs=p.rooms||[],beds=rs.filter(r=>r.type==='bedroom'),living=rs.find(r=>r.type==='living'),others=rs.filter(r=>r!==living&&!beds.includes(r));function add(r,x,y){const e=document.createElement('div');e.className='room';e.dataset.i=rs.indexOf(r);e.style.width=Math.max(55,r.width*18)+'px';e.style.height=Math.max(40,r.depth*18)+'px';e.style.left=x+'px';e.style.top=y+'px';e.innerHTML=`<div><div class="room-name">${esc(r.name)}</div><div class="room-size">${r.width} × ${r.depth} m</div></div><span class="resize"></span>`;b.appendChild(e);bind(e)}if(living)add(living,430-living.width*9,270-living.depth*9);const sp=[[330,55],[650,55],[235,245],[765,245],[330,470],[650,470],[60,70],[800,70],[60,430],[800,430]];beds.forEach((r,i)=>{const p=sp[i]||[80+(i%3)*260,80+Math.floor(i/3)*400];add(r,p[0],p[1])});others.forEach((r,i)=>{const p=sp[(beds.length+i)%sp.length];add(r,Math.min(860,p[0]+(i%2)*55),Math.min(520,p[1]+(i%3)*35))});$('summary').style.display='block';$('summaryInner').innerHTML=`<div><strong>${esc(p.title||'AI House Concept')}</strong><span>Concept</span></div><div><strong>${p.house_width} × ${p.house_depth} m</strong><span>Footprint</span></div><div><strong>${beds.length}</strong><span>Bedrooms</span></div><div><strong>${rs.length}</strong><span>Spaces</span></div>`}function bind(e){let drag=false,res=false,sx,sy,sl,st,sw,sh;e.onpointerdown=x=>{res=x.target.classList.contains('resize');drag=!res;state.selected=+e.dataset.i;select(e);sx=x.clientX;sy=x.clientY;sl=e.offsetLeft;st=e.offsetTop;sw=e.offsetWidth;sh=e.offsetHeight;e.setPointerCapture(x.pointerId)};e.onpointermove=x=>{if(!drag&&!res)return;const dx=x.clientX-sx,dy=x.clientY-sy;if(drag){e.style.left=Math.max(20,sl+dx)+'px';e.style.top=Math.max(20,st+dy)+'px'}else{e.style.width=Math.max(55,sw+dx)+'px';e.style.height=Math.max(40,sh+dy)+'px'}};e.onpointerup=()=>{drag=res=false;update3D()}}function select(e){document.querySelectorAll('.room').forEach(x=>x.classList.remove('selected'));e.classList.add('selected');const r=state.plan.rooms[+e.dataset.i];$('inspector').style.display='flex';$('roomName').value=r.name;$('roomW').value=r.width;$('roomD').value=r.depth}$('applyEdit').onclick=()=>{if(state.selected===null)return;const r=state.plan.rooms[state.selected];r.name=$('roomName').value.trim()||r.name;r.width=Math.max(.5,+$('roomW').value||r.width);r.depth=Math.max(.5,+$('roomD').value||r.depth);renderPlan(state.plan);$('inspector').style.display='flex';update3D()};$('deleteRoom').onclick=()=>{if(state.selected===null)return;state.plan.rooms.splice(state.selected,1);state.selected=null;$('inspector').style.display='none';renderPlan(state.plan);update3D()};
let scene,camera,renderer,controls,root;function init3D(){if(scene)return;scene=new THREE.Scene();scene.background=new THREE.Color(0xdfe5df);camera=new THREE.PerspectiveCamera(48,1,.1,2000);renderer=new THREE.WebGLRenderer({antialias:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));root=$('threeRoot');root.appendChild(renderer.domElement);controls=new THREE.OrbitControls(camera,renderer.domElement);controls.enableDamping=true;scene.add(new THREE.HemisphereLight(0xffffff,0x66705f,2.4));const s=new THREE.DirectionalLight(0xffffff,3);s.position.set(25,40,20);scene.add(s);const f=new THREE.DirectionalLight(0xfff0d0,1);f.position.set(-25,15,-10);scene.add(f);window.addEventListener('resize',resize3D);animate()}function resize3D(){if(!renderer)return;const r=root.getBoundingClientRect();camera.aspect=Math.max(1,r.width)/Math.max(1,r.height);camera.updateProjectionMatrix();renderer.setSize(r.width,r.height,false)}function render3D(){init3D();resize3D();if(root.group)scene.remove(root.group);const g=new THREE.Group();root.group=g;scene.add(g);const rs=state.plan.rooms||[],els=document.querySelectorAll('.room');let minX=9999,minY=9999,maxX=0,maxY=0;els.forEach(e=>{minX=Math.min(minX,e.offsetLeft);minY=Math.min(minY,e.offsetTop);maxX=Math.max(maxX,e.offsetLeft+e.offsetWidth);maxY=Math.max(maxY,e.offsetTop+e.offsetHeight)});const sc=.055,ox=(minX+maxX)/2,oy=(minY+maxY)/2;const floor=new THREE.Mesh(new THREE.BoxGeometry(Math.max(20,(maxX-minX)*sc),.25,Math.max(20,(maxY-minY)*sc)),new THREE.MeshStandardMaterial({color:0xc7c0b2,roughness:.8}));floor.position.y=-.2;g.add(floor);els.forEach(e=>{const r=rs[+e.dataset.i],x=(e.offsetLeft+e.offsetWidth/2-ox)*sc,z=(e.offsetTop+e.offsetHeight/2-oy)*sc,w=Math.max(.8,e.offsetWidth*sc),d=Math.max(.8,e.offsetHeight*sc),h=r.type==='courtyard'?.12:3;const m=new THREE.MeshStandardMaterial({color:r.type==='courtyard'?0x7c9470:(r.type==='bedroom'?0xd8c9ae:0xe6dfd1),roughness:.72});const q=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),m);q.position.set(x,h/2,z);g.add(q)});camera.position.set(24,22,28);controls.target.set(0,0,0);controls.update()}function update3D(){if(scene&&state.plan&&threeView.classList.contains('active'))render3D()}function animate(){requestAnimationFrame(animate);if(controls)controls.update();if(renderer&&scene)renderer.render(scene,camera)}$('threeTop').onclick=()=>{camera.position.set(0,45,.01);controls.target.set(0,0,0);controls.update()};$('threeIso').onclick=()=>{camera.position.set(24,22,28);controls.target.set(0,0,0);controls.update()};$('threeFront').onclick=()=>{camera.position.set(0,10,38);controls.target.set(0,2,0);controls.update()};
$('generateBtn').onclick=async()=>{status();const q=missing();if(q){addMsg(q);return}$('loading').style.display='flex';try{const fd=new FormData();fd.append('plot_width',state.plotW);fd.append('plot_depth',state.plotD);fd.append('bedrooms',state.bedrooms||'');fd.append('total_spaces',state.totalSpaces||'');fd.append('brief',state.brief.join('\n'));const r=await fetch('api/generate.php',{method:'POST',body:fd});const j=await r.json();if(!j.ok){addMsg(j.message||'AI generation failed.','system');return}if(j.plan?.needs_clarification){(j.plan.questions||[]).forEach(q=>addMsg(q));return}renderPlan(j.plan);addMsg('Concept imekamilika. Sasa unaweza kuhamisha rooms, kubadilisha dimensions, na kuangalia 3D.');$('planState').textContent='AI plan ready · editable'}catch(e){addMsg('Kuna tatizo la connection wakati wa kutengeneza plan. Jaribu tena.','system')}finally{$('loading').style.display='none'}};$('resetBtn').onclick=()=>{state.plan=null;state.selected=null;$('inspector').style.display='none';$('summary').style.display='none';$('emptyPlan').style.display='grid';document.querySelectorAll('.room').forEach(x=>x.remove());$('planState').textContent='Waiting for your brief…';addMsg('Plan ime-reset. Mazungumzo yako bado yamehifadhiwa.','system')};
</script></body></html>